import { toast } from 'react-toastify';

import { removeFromStockStock } from '../config/api';

export default function RemoveButton({ item, onUpdate }) {
  async function onSelect() {
    
     try {
      await removeFromStockStock(item.foodName)
      toast(item.foodName + " has been removed")
     
     if (onUpdate ) {
                onUpdate (item.foodName)
            }
        } catch (error) {

            toast("There has been an error " + error + " with " + item.foodName + " please try again!")
        }
  }

  return (
    <button
      className="bg-red-500 w-full font-bold text-white px-4 py-2 rounded"
      onClick={onSelect}>Remove</button>

  )
}
